import 'outbound_failure_command.dart';

/// The four shipper-owned writes for a redelivery task.
///
/// A redelivery is a free delivery of the immutable plan released by the
/// manager after inspection.  It never creates a new COD obligation, changes
/// stock, or increments the outbound attempt counter.  Request IDs are
/// generated by the ViewModel and must be reused when a write result is
/// uncertain.
enum RedeliveryOperation {
  accept('accept_redelivery_task'),
  start('start_redelivery_task'),
  complete('complete_redelivery'),
  fail('fail_redelivery_task');

  const RedeliveryOperation(this.value);

  final String value;

  String get rpcName => value;

  static RedeliveryOperation fromValue(String value) {
    for (final operation in values) {
      if (operation.value == value) return operation;
    }
    throw FormatException('Unknown redelivery operation: $value');
  }

  // Readable aliases for callers using the RPC vocabulary.
  static const acceptTask = RedeliveryOperation.accept;
  static const startTask = RedeliveryOperation.start;
  static const completeTask = RedeliveryOperation.complete;
  static const failTask = RedeliveryOperation.fail;
}

/// One row in the immutable redelivery plan.
///
/// Only the server-approved item UUID and quantity cross the command boundary;
/// names, prices and return evidence remain in the authorized detail read.
class RedeliveryItem {
  const RedeliveryItem({required this.itemId, required this.quantity});

  final String itemId;
  final int quantity;

  String get returnItemId => itemId;
  int get quantityToDeliver => quantity;

  bool get hasUuidShape => _uuid.hasMatch(itemId);
  bool get hasValidQuantity => quantity >= 1 && quantity <= _maxInt32;
  bool get isValid => hasUuidShape && hasValidQuantity;

  Map<String, dynamic> toJson() => <String, dynamic>{
    'item_id': itemId,
    'quantity': quantity,
  };

  @override
  bool operator ==(Object other) =>
      other is RedeliveryItem &&
      itemId == other.itemId &&
      quantity == other.quantity;

  @override
  int get hashCode => Object.hash(itemId, quantity);

  @override
  String toString() => 'RedeliveryItem(itemId: $itemId, quantity: $quantity)';
}

/// Immutable idempotent input for one redelivery write.
///
/// [returnRequestId] and [orderId] are local snapshot guards.  The RPC derives
/// both values from [taskId]; they are intentionally not sent as parameters.
class RedeliveryCommand {
  RedeliveryCommand({
    required this.taskId,
    required this.requestId,
    required this.returnRequestId,
    required this.orderId,
    required this.operation,
    Iterable<RedeliveryItem> items = const <RedeliveryItem>[],
    this.receivedAllItems,
    this.reason,
    this.description,
  }) : items = List<RedeliveryItem>.unmodifiable(items);

  RedeliveryCommand.accept({
    required String taskId,
    required String requestId,
    required String returnRequestId,
    required String orderId,
    required Iterable<RedeliveryItem> items,
  }) : this(
         taskId: taskId,
         requestId: requestId,
         returnRequestId: returnRequestId,
         orderId: orderId,
         operation: RedeliveryOperation.accept,
         items: items,
       );

  RedeliveryCommand.start({
    required String taskId,
    required String requestId,
    required String returnRequestId,
    required String orderId,
  }) : this(
         taskId: taskId,
         requestId: requestId,
         returnRequestId: returnRequestId,
         orderId: orderId,
         operation: RedeliveryOperation.start,
       );

  RedeliveryCommand.complete({
    required String taskId,
    required String requestId,
    required String returnRequestId,
    required String orderId,
    bool receivedAllItems = true,
  }) : this(
         taskId: taskId,
         requestId: requestId,
         returnRequestId: returnRequestId,
         orderId: orderId,
         operation: RedeliveryOperation.complete,
         receivedAllItems: receivedAllItems,
       );

  RedeliveryCommand.fail({
    required String taskId,
    required String requestId,
    required String returnRequestId,
    required String orderId,
    required OutboundFailureReason reason,
    String? description,
  }) : this(
         taskId: taskId,
         requestId: requestId,
         returnRequestId: returnRequestId,
         orderId: orderId,
         operation: RedeliveryOperation.fail,
         reason: reason,
         description: description,
       );

  final String taskId;
  final String requestId;
  final String returnRequestId;
  final String orderId;
  final RedeliveryOperation operation;
  final List<RedeliveryItem> items;
  final bool? receivedAllItems;
  final OutboundFailureReason? reason;
  final String? description;

  String get returnId => returnRequestId;
  String get stableRequestId => requestId;
  String get requestKey => requestId;
  RedeliveryOperation get action => operation;
  bool get isAccept => operation == RedeliveryOperation.accept;
  bool get isStart => operation == RedeliveryOperation.start;
  bool get isComplete => operation == RedeliveryOperation.complete;
  bool get isFail => operation == RedeliveryOperation.fail;
  bool get isFailure => isFail;
  OutboundFailureReason? get failureReason => reason;
  String? get trimmedDescription {
    final text = description?.trim();
    return text == null || text.isEmpty ? null : text;
  }

  bool get hasUuidShape =>
      _uuid.hasMatch(taskId) &&
      _uuid.hasMatch(requestId) &&
      _uuid.hasMatch(returnRequestId) &&
      _uuid.hasMatch(orderId);

  bool get hasNonBlankIds =>
      taskId.trim().isNotEmpty &&
      requestId.trim().isNotEmpty &&
      returnRequestId.trim().isNotEmpty &&
      orderId.trim().isNotEmpty;

  bool get hasCanonicalItems {
    if (items.isEmpty) return false;
    String? previous;
    final seen = <String>{};
    for (final item in items) {
      if (!item.isValid) return false;
      final id = item.itemId.toLowerCase();
      if (!seen.add(id)) return false;
      if (previous != null && id.compareTo(previous) < 0) return false;
      previous = id;
    }
    return true;
  }

  bool get hasValidDescription {
    if (reason != OutboundFailureReason.other) return true;
    final text = trimmedDescription;
    return text != null && text.isNotEmpty;
  }

  bool get isValid {
    if (!hasUuidShape || !hasNonBlankIds) return false;
    return switch (operation) {
      RedeliveryOperation.accept =>
        reason == null &&
            description == null &&
            receivedAllItems == null &&
            hasCanonicalItems,
      RedeliveryOperation.start =>
        reason == null &&
            description == null &&
            receivedAllItems == null &&
            items.isEmpty,
      RedeliveryOperation.complete =>
        reason == null &&
            description == null &&
            receivedAllItems == true &&
            items.isEmpty,
      RedeliveryOperation.fail =>
        items.isEmpty &&
            receivedAllItems == null &&
            reason != null &&
            hasValidDescription,
    };
  }

  @override
  bool operator ==(Object other) =>
      other is RedeliveryCommand &&
      taskId == other.taskId &&
      requestId == other.requestId &&
      returnRequestId == other.returnRequestId &&
      orderId == other.orderId &&
      operation == other.operation &&
      _sameItems(items, other.items) &&
      receivedAllItems == other.receivedAllItems &&
      reason == other.reason &&
      description == other.description;

  @override
  int get hashCode => Object.hash(
    taskId,
    requestId,
    returnRequestId,
    orderId,
    operation,
    Object.hashAll(items),
    receivedAllItems,
    reason,
    description,
  );

  @override
  String toString() =>
      'RedeliveryCommand(operation: ${operation.value}, taskId: $taskId, '
      'requestId: $requestId, items: ${items.length}, '
      'hasReason: ${reason != null})';

  static bool _sameItems(
    List<RedeliveryItem> left,
    List<RedeliveryItem> right,
  ) {
    if (left.length != right.length) return false;
    for (var index = 0; index < left.length; index++) {
      if (left[index] != right[index]) return false;
    }
    return true;
  }
}

/// Validated receipt for one committed redelivery transaction.
class RedeliveryAck {
  const RedeliveryAck({
    required this.taskId,
    required this.returnRequestId,
    required this.orderId,
    required this.operation,
    required this.taskStatus,
    required this.returnStatus,
    required this.eventId,
    required this.requestId,
    required this.occurredAt,
    this.acceptedAt,
    this.startedAt,
    this.completedAt,
    this.closedAt,
    this.failedAt,
    this.reason,
    this.description,
    this.custodyOpen = false,
  });

  final String taskId;
  final String returnRequestId;
  final String orderId;
  final RedeliveryOperation operation;
  final String taskStatus;
  final String returnStatus;
  final String eventId;
  final String requestId;
  final DateTime occurredAt;
  final DateTime? acceptedAt;
  final DateTime? startedAt;
  final DateTime? completedAt;
  final DateTime? closedAt;
  final DateTime? failedAt;
  final OutboundFailureReason? reason;
  final String? description;
  final bool custodyOpen;

  bool get isAccept => operation == RedeliveryOperation.accept;
  bool get isStart => operation == RedeliveryOperation.start;
  bool get isComplete => operation == RedeliveryOperation.complete;
  bool get isFailure => operation == RedeliveryOperation.fail;

  bool matches(RedeliveryCommand command) =>
      taskId.toLowerCase() == command.taskId.toLowerCase() &&
      returnRequestId.toLowerCase() == command.returnRequestId.toLowerCase() &&
      orderId.toLowerCase() == command.orderId.toLowerCase() &&
      requestId.toLowerCase() == command.requestId.toLowerCase() &&
      operation == command.operation;
}

const int _maxInt32 = 2147483647;
final RegExp _uuid = RegExp(
  r'^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-'
  r'[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$',
);

typedef RedeliveryCommandItem = RedeliveryItem;
typedef RedeliveryFailureReason = OutboundFailureReason;
typedef RedeliveryAckResult = RedeliveryAck;
typedef RedeliveryCommandOperation = RedeliveryOperation;
